function totalWidth(boxSizing, width, padding, border, margin) {
  const pad = padding * 2, bd = border * 2, mg = margin * 2;
  const borderBox = boxSizing === 'border-box' ? width : width + pad + bd;
  const content = boxSizing === 'border-box' ? width - pad - bd : width;
  return { boxSizing, content, borderBox, outerWithMargin: borderBox + mg };
}
